/*
 * SVG typings for the Bitburner React panel.
 *
 * `NetscriptGlobals.d.ts` is generated by the game and its curated React subset
 * declares only the HTML intrinsic elements, so every SVG tag falls back to
 * `HTMLAttributes<any>` and rejects `width` / `x1` / `points`. `React.SVGProps`
 * is not part of that curated subset either, so the elements this project
 * actually renders are declared here rather than in the generated file.
 *
 * Extend these interfaces when a new SVG element or attribute is used.
 */

interface SvgPresentationProps {
    readonly style?: Record<string, unknown>;
    readonly fill?: string;
    readonly stroke?: string;
    readonly strokeWidth?: number | string;
    readonly children?: unknown;
}

interface SvgRootProps extends SvgPresentationProps {
    readonly width?: number;
    readonly height?: number;
}

interface SvgLineProps extends SvgPresentationProps {
    readonly x1?: number;
    readonly y1?: number;
    readonly x2?: number;
    readonly y2?: number;
}

interface SvgPolylineProps extends SvgPresentationProps {
    readonly points?: string;
}

interface SvgTextProps extends SvgPresentationProps {
    readonly x?: number;
    readonly y?: number;
    readonly textAnchor?: string;
    readonly fontSize?: string;
    readonly fontFamily?: string;
}

declare global {
    namespace JSX {
        interface IntrinsicElements {
            svg: SvgRootProps;
            line: SvgLineProps;
            polyline: SvgPolylineProps;
            text: SvgTextProps;
        }
    }
}

export {};
